import ifcopenshell
import ifcopenshell.util.element

# Load the duplex model which has violations
path_ifc_model = '/home/sffc348/Repos/cobbie/acc/bim_models/duplex/arc.ifc'
model = ifcopenshell.open(path_ifc_model)

# Get first door
doors = model.by_type('IfcDoor')
if doors:
    door = doors[0]
    print(f"Door: {door.Name} (GUID: {door.GlobalId})")
    print(f"\nDoor attributes:")
    for attr in dir(door):
        if not attr.startswith('_') and not callable(getattr(door, attr)):
            try:
                val = getattr(door, attr)
                if val is not None:
                    print(f"  {attr}: {val}")
            except:
                pass

    print(f"\nDoor inverse attributes:")
    # Get inverses
    inverses = model.get_inverse(door)
    print(f"Total inverses: {len(inverses)}")
    for inv in inverses:
        print(f"  Type: {inv.is_a()}, ID: {inv.id()}")
        if inv.is_a('IfcRelFillsElement'):
            print(f"    RelatingOpeningElement: {inv.RelatingOpeningElement}")
            opening = inv.RelatingOpeningElement
            # Get opening's inverses to find the wall
            opening_inverses = model.get_inverse(opening)
            for o_inv in opening_inverses:
                if o_inv.is_a('IfcRelVoidsElement'):
                    print(f"    Found IfcRelVoidsElement, RelatingBuildingElement: {o_inv.RelatingBuildingElement}")

import ifcopenshell
import ifcopenshell.util.element
from typing import List

# Check the dental_clinic door that was flagged
path_dental = '/home/sffc348/Repos/cobbie/acc/bim_models/dental_clinic/arc.ifc'
model = ifcopenshell.open(path_dental)

guid = '3eIXtbz01CQuZOCQ8qhuxf'
elem = model.by_guid(guid)
print(f"Element: {elem.Name}, Type: {elem.is_a()}")
print(f"GlobalId: {elem.GlobalId}")

# Check all inverse relationships
print("\nAll inverse attributes:")
for attr_name in dir(elem):
    if attr_name.startswith('Has') or attr_name.startswith('ContainedIn') or attr_name.startswith('Decomposes') or attr_name.startswith('IsDecomposedBy'):
        try:
            val = getattr(elem, attr_name)
            if val and not callable(val):
                if hasattr(val, '__iter__') and not isinstance(val, str):
                    val_list = list(val)
                    if val_list:
                        print(f"  {attr_name}: {[v.is_a() if hasattr(v, 'is_a') else type(v) for v in val_list[:3]]}")
                else:
                    print(f"  {attr_name}: {val}")
        except:
            pass

# Check if it's related to any other element types
print("\nChecking all relationship types for this element:")
for rel in model.by_type('IfcRelAssociates'):
    if hasattr(rel, 'RelatedObjects'):
        for obj in rel.RelatedObjects:
            if obj.id() == elem.id():
                print(f"  Found in IfcRelAssociates")

# Check type of the door
door_type = ifcopenshell.util.element.get_type(elem)
print(f"\nDoor type: {door_type.Name if door_type else None}")

# Get all properties
psets = ifcopenshell.util.element.get_psets(elem)
print(f"\nProperty sets: {list(psets.keys())}")

# Check if there are IfcRelNests relationships (aggregations)
print("\nChecking IfcRelAggregates/IfcRelNests:")
for rel in model.by_type('IfcRelAggregates'):
    if hasattr(rel, 'RelatedObjects'):
        for obj in rel.RelatedObjects:
            if obj.id() == elem.id():
                parent = rel.RelatingObject
                print(f"  Aggregated by: {parent.Name} ({parent.is_a()})")

for rel in model.by_type('IfcRelNests'):
    if hasattr(rel, 'RelatedObjects'):
        for obj in rel.RelatedObjects:
            if obj.id() == elem.id():
                parent = rel.RelatingObject
                print(f"  Nested in: {parent.Name} ({parent.is_a()})")

# Also check the container decomposition
container = ifcopenshell.util.element.get_container(elem)
if container:
    print(f"\nContainer: {container.Name} ({container.is_a()})")
    print(f"Container contains {len(list(ifcopenshell.util.element.get_decomposition(container)))} elements")
